public sealed record ToolError(string Code, string Message, string? Field = null, bool Retryable = false);

public static class McpToolResult
{
    public static McpToolResult Error(ToolError error) => new(error);
    public static McpToolResult NotFound(string message) => new(new ToolError("not_found", message, retryable: false));
    public static McpToolResult Success(string payload) => new(payload);
}
